#!/usr/bin/env python3
"""The test_no_move_seam tests were split (TD-11c): the parts hold the checks and no_move_seam_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_no_move_seam.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from no_move_seam_common import raised, rig, verdict  # noqa: E402,F401

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["raised", "rig", "verdict"]

PARTS = ("test_no_move_seam_n1_n9", "test_no_move_seam_n2b_n15", "test_no_move_seam_sites", "test_no_move_seam_k4s", "test_no_move_seam_c26_g27_f2")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_no_move_seam.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
